    "audience": "academic-conference",
    "tone": "academic, data-forward",
    "venue": "IPCC AR6 Synthesis Report Dissemination — Climate Science Conference"
  },
  "brief": {
    "title": "Climate Change 2023: Key Findings from the IPCC Sixth Assessment Synthesis Report",
    "one_liner": "A visual summary of the most critical findings from the IPCC AR6 Synthesis Report, highlighting observed changes, future projections, and urgent pathways for climate action.",
    "goal": "The viewer should understand the scale and urgency of climate change as documented by the IPCC AR6 cycle, grasp the key temperature and emissions trajectories, and recognize the window for meaningful mitigation and adaptation action."
  },
  "sections": [
    {
      "id": "observed-changes",
      "title": "Observed Changes and Current State",
      "objective": "Present the documented evidence of climate change including global temperature rise, greenhouse gas concentrations, and observed impacts across systems."
    },
    {
      "id": "future-projections",
      "title": "Future Projections Under Different Scenarios",
      "objective": "Illustrate how global warming trajectories differ across SSP scenarios and what each pathway means for temperature, sea level, and extreme events."
    },
    {
      "id": "risks-and-impacts",
      "title": "Risks, Vulnerabilities, and Cascading Impacts",
      "objective": "Highlight the disproportionate risks to vulnerable populations and ecosystems, and the compounding nature of climate hazards."
    },
    {
      "id": "mitigation-pathways",
      "title": "Mitigation and Adaptation Pathways",
      "objective": "Summarize the emissions reduction requirements to limit warming to 1.5°C and 2°C, and outline key adaptation strategies."
    },
    {
      "id": "call-to-action",
      "title": "The Narrowing Window for Action",
      "objective": "Convey the urgency of immediate, deep, and sustained action across all sectors and scales to secure a liveable future."
    }
  ],
  "metrics": [
    {
      "label": "Global surface temperature increase (2011–2020 vs. 1850–1900)",
      "value": "1.1°C"
    },
    {
      "label": "CO₂ concentration in 2019",
      "value": "410 ppm (highest in 2 million years)"
    },
    {
      "label": "Global GHG emissions in 2019",
      "value": "~59 GtCO₂e"
    },
    {
      "label": "Remaining carbon budget for 1.5°C (50% likelihood, from 2020)",
      "value": "~500 GtCO₂"
    },
    {
      "label": "Required GHG reduction by 2030 for 1.5°C pathway",
      "value": "43% below 2019 levels"
    },
    {
      "label": "Sea level rise (1901–2018)",
      "value": "~0.20 m"
    },
    {
      "label": "Population exposed to severe climate hazards",
      "value": "3.3–3.6 billion people"
    }
  ]
}

