\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── IPCC Climate Color Theme: Deep navy + warm accents ──
\definecolor{primary}{HTML}{0F2A4A}       % deep navy
\definecolor{secondary}{HTML}{C75B12}     % warm amber/vermilion
\definecolor{accent}{HTML}{B91C1C}        % deep red
\definecolor{teal}{HTML}{0E7490}          % cool teal for solutions
\definecolor{bgposter}{HTML}{E8ECF2}      % soft blue-gray poster bg
\definecolor{redbg}{HTML}{FFF5F0}         % warm tint for observed cards
\definecolor{bluebg}{HTML}{EEF2F8}        % cool tint for projection cards
\definecolor{darkbg}{HTML}{F0F4F8}        % slate tint for method cards
\definecolor{tealbg}{HTML}{ECFDF5}        % green tint for solutions
\definecolor{redtitlebg}{HTML}{FDEBD0}    % amber title bg
\definecolor{bluetitlebg}{HTML}{D6E4F0}   % blue title bg
\definecolor{darktitlebg}{HTML}{D1DAE6}   % slate title bg
\definecolor{tealtitlebg}{HTML}{D1FAE5}   % green title bg
\definecolor{textdark}{HTML}{1A202C}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{stathighlight}{HTML}{FEF3C7} % warm amber highlight
\definecolor{statred}{HTML}{FEE2E2}       % red highlight
\definecolor{statblue}{HTML}{DBEAFE}      % blue highlight
\definecolor{warmbar}{HTML}{D97706}       % amber accent bar
\definecolor{urgentred}{HTML}{DC2626}     % urgent red

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Sub-header command ──
\newcommand{\subheader}[1]{%
  {\fontsize{36}{44}\selectfont\bfseries\color{primary}#1}\par\vspace{4pt}%
}

% ── Stat callout command ──
\newcommand{\statcallout}[3]{%
  \begin{minipage}[c]{\linewidth}\centering
    \fcolorbox{#3!40}{#3}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} #1}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{textdark} #2}\vspace{8pt}%
    }}
  \end{minipage}%
}

% ── Card styles ──
\tcbset{
  observedcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  projcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  riskcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=statred,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  solutioncard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{teal},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=tealtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={teal!50},
    valign=top, drop shadow={opacity=0.15},
  },
  urgentcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!12!white,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════
% TITLE BAR (rows 1-3)
% ══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=18pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{76}{92}\selectfont\bfseries Climate Change 2023}\\[12pt]
  {\fontsize{48}{58}\selectfont Key Findings from the IPCC Sixth Assessment}\\[10pt]
  {\fontsize{48}{58}\selectfont Synthesis Report}\\[16pt]
  {\fontsize{30}{38}\selectfont\color{white!75} Intergovernmental Panel on Climate Change\quad$\vert$\quad AR6 Cycle (2021--2023)\quad$\vert$\quad ipcc.ch}
}

% ══════════════════════════════════════════
% HEADLINE METRICS BANNER (rows 4-6)
% ══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!8!white, boxrule=0pt, arc=0pt,
  left=14pt, right=14pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary} +1.1\,\textdegree C}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Global temperature rise}\\
      {\fontsize{20}{26}\selectfont\color{textgray} 2011--2020 vs.\ 1850--1900}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary} 410\,ppm}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Atmospheric CO\textsubscript{2}}\\
      {\fontsize{20}{26}\selectfont\color{textgray} Highest in 2 million years}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent!40}{statred}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{accent} 3.3--3.6\,B}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} People exposed to}\\
      {\fontsize{22}{28}\selectfont\color{textdark} severe climate hazards}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent!40}{statred}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 43\%}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} GHG reduction by 2030}\\
      {\fontsize{20}{26}\selectfont\color{textgray} Required for 1.5\,\textdegree C}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ Second row of stats ══
\posterbox[
  enhanced, colback=primary!8!white, boxrule=0pt, arc=0pt,
  left=14pt, right=14pt, top=6pt, bottom=10pt,
  valign=center, borderline south={4pt}{0pt}{secondary!60},
]{name=stats2, column=1, span=3, between=row7 and row9}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!30}{statblue}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{primary} \raisebox{0pt}{\texttildelow}59\,GtCO\textsubscript{2}e}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Global GHG emissions (2019)}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!30}{statblue}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{primary} \raisebox{0pt}{\texttildelow}500\,GtCO\textsubscript{2}}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Remaining carbon budget for 1.5\,\textdegree C}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!30}{statblue}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{primary} \raisebox{0pt}{\texttildelow}0.20\,m}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Sea level rise (1901--2018)}\vspace{6pt}%
    }}
  \end{minipage}
}


% ══════════════════════════════════════════
% COLUMN 1: Observed Changes + Mitigation
% ══════════════════════════════════════════

% -- Observed Changes --
\posterbox[observedcard, title={Observed Changes \& Current State}
]{name=observed, column=1, between=row9 and row14}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Global surface temperature: \textbf{+1.1\,\textdegree C} above pre-industrial
    \item CO\textsubscript{2} at \textbf{410\,ppm} --- highest in 2 million years
    \item GHG emissions: \textbf{\raisebox{0pt}{\texttildelow}59\,GtCO\textsubscript{2}e} in 2019
    \item Arctic sea ice: \textbf{\raisebox{0pt}{\texttildelow}40\% area loss} since 1979
    \item Sea level rose \textbf{\raisebox{0pt}{\texttildelow}0.20\,m} over 1901--2018
  \end{itemize}
  \vspace{8pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\color{textdark} Every region has experienced increases in\\extreme weather frequency and intensity}%
    \vspace{6pt}%
  }}
}

% -- Mitigation Pathways --
\posterbox[solutioncard, title={Mitigation \& Adaptation Pathways}
]{name=mitigation, column=1, between=row14 and row20}{
  \fontsize{32}{42}\selectfont
  \subheader{1.5\,\textdegree C Pathway Requirements}
  \begin{itemize}[itemsep=8pt]
    \item GHG emissions: \textbf{$-$43\%} by 2030 (vs.\ 2019)
    \item Reach \textbf{net zero CO\textsubscript{2}} by $\sim$2050
    \item Carbon budget: only \textbf{\raisebox{0pt}{\texttildelow}500\,GtCO\textsubscript{2}} remaining
  \end{itemize}
  \vspace{6pt}
  \subheader{2\,\textdegree C Pathway}
  \begin{itemize}[itemsep=8pt]
    \item Emissions: \textbf{$-$27\%} by 2030
    \item Net zero CO\textsubscript{2} by $\sim$2070
  \end{itemize}
  \vspace{8pt}
  \colorbox{teal!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\color{textdark}\textbf{Key levers:} Energy decarbonization,\\transport electrification, demand-side efficiency,\\carbon sink restoration}%
    \vspace{6pt}%
  }}
}


% ══════════════════════════════════════════
% COLUMN 2: Projections + Narrowing Window
% ══════════════════════════════════════════

% -- Future Projections --
\posterbox[projcard, title={Future Projections: SSP Scenarios}
]{name=projections, column=2, between=row9 and row15}{
  \fontsize{32}{42}\selectfont

  \vspace{4pt}
  \renewcommand{\arraystretch}{1.5}
  \centering
  {\fontsize{28}{36}\selectfont
  \begin{tabular}{p{4.8cm} >{\centering\arraybackslash}p{3cm} p{7cm}}
    \rowcolor{primary!15}
    \textbf{Scenario} & \textbf{Warming} & \textbf{Description} \\
    SSP1-1.9 & +1.4\,\textdegree C & Very low emissions \\
    \rowcolor{primary!8}
    SSP1-2.6 & +1.8\,\textdegree C & Low emissions \\
    SSP2-4.5 & +2.7\,\textdegree C & Intermediate \\
    \rowcolor{accent!12}
    SSP3-7.0 & +3.6\,\textdegree C & High emissions \\
    \rowcolor{accent!20}
    SSP5-8.5 & \textbf{+4.4\,\textdegree C} & Very high emissions \\
  \end{tabular}}

  \vspace{10pt}
  \subheader{Sea Level Rise by 2100}
  \begin{itemize}[itemsep=8pt]
    \item SSP1-1.9: \textbf{0.28--0.55\,m}
    \item SSP5-8.5: \textbf{0.63--1.01\,m}
    \item Continued rise for \textbf{centuries to millennia}
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\color{textdark} Under SSP5-8.5, warming could exceed\\
    \textbf{4.4\,\textdegree C by 2100}}%
    \vspace{6pt}%
  }}
}

% -- Narrowing Window --
\posterbox[urgentcard, title={The Narrowing Window for Action}
]{name=window, column=2, between=row15 and row20}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt, label={\color{accent}$\blacktriangleright$}]
    \item Choices \textbf{this decade} determine 1.5\,\textdegree C feasibility
    \item Delayed action $\Rightarrow$ higher costs, locked-in carbon infrastructure
    \item Climate finance: \textbf{3--6$\times$ short} of adaptation needs
  \end{itemize}
  \vspace{8pt}
  \colorbox{accent!25}{\parbox{0.94\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{34}{42}\selectfont\bfseries\color{accent} Immediate, deep, and sustained}\\[4pt]
    {\fontsize{34}{42}\selectfont\bfseries\color{accent} emissions reductions are essential}\\[4pt]
    {\fontsize{30}{38}\selectfont\color{textdark} to secure a liveable future for all}%
    \vspace{8pt}%
  }}
}


% ══════════════════════════════════════════
% COLUMN 3: Risks + Source Info
% ══════════════════════════════════════════

% -- Risks & Vulnerabilities --
\posterbox[riskcard, title={Risks, Vulnerabilities \& Cascading Impacts}
]{name=risks, column=3, between=row9 and row15}{
  \fontsize{32}{42}\selectfont

  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{48}{58}\selectfont\bfseries\color{accent} 3.3--3.6 billion}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{textdark} people highly vulnerable to climate change}%
    \vspace{8pt}%
  }}

  \vspace{10pt}
  \subheader{Compounding Risks}
  \begin{itemize}[itemsep=8pt]
    \item Climate hazards interact with poverty, inequality, ecosystem degradation
    \item Biodiversity: \textbf{14\% of species} face very high extinction risk at 1.5\,\textdegree C
  \end{itemize}

  \vspace{8pt}
  \subheader{Sectoral Impacts}
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Food:} Crop yield growth slowing; tropical fisheries declining
    \item \textbf{Water:} $>$50\% of population faces severe scarcity $\geq$1 month/year
    \item \textbf{Health:} Heat mortality \& vector-borne disease expanding
  \end{itemize}
}

% -- Source & Reference --
\posterbox[projcard, title={Source \& Reference}
]{name=source, column=3, between=row15 and row20}{
  \fontsize{30}{40}\selectfont

  \colorbox{primary!15}{\parbox{0.94\linewidth}{%
    \vspace{6pt}%
    {\fontsize{28}{36}\selectfont
    \textbf{Citation:} IPCC, 2023. \textit{AR6 Synthesis Report: Climate Change 2023.} Intergovernmental Panel on Climate Change.}\vspace{6pt}%
  }}

  \vspace{10pt}
  {\fontsize{28}{36}\selectfont
  \textbf{Data sources:}
  \begin{itemize}[itemsep=6pt, label={\color{primary}$\bullet$}]
    \item Working Group I: Physical Science Basis
    \item Working Group II: Impacts, Adaptation
    \item Working Group III: Mitigation
    \item Special Reports: 1.5\,\textdegree C, Ocean \& Cryosphere, Land
  \end{itemize}
  }

  \vspace{8pt}
  \centering
  {\fontsize{30}{38}\selectfont\color{primary}\textbf{ipcc.ch/assessment-report/ar6}}
}


\end{tcbposter}
\end{document}
