% COLUMN 3: Risks + Source Info
% ══════════════════════════════════════════

% -- Risks & Vulnerabilities --
\posterbox[riskcard, title={Risks, Vulnerabilities \& Cascading Impacts}
]{name=risks, column=3, between=row9 and row15}{
  \fontsize{32}{42}\selectfont

  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{48}{58}\selectfont\bfseries\color{accent} 3.3--3.6 billion}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{textdark} people highly vulnerable to climate change}%
    \vspace{8pt}%
  }}

  \vspace{10pt}
  \subheader{Compounding Risks}
  \begin{itemize}[itemsep=8pt]
    \item Climate hazards interact with poverty, inequality, ecosystem degradation
    \item Biodiversity: \textbf{14\% of species} face very high extinction risk at 1.5\,\textdegree C
  \end{itemize}

  \vspace{8pt}
  \subheader{Sectoral Impacts}
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Food:} Crop yield growth slowing; tropical fisheries declining
    \item \textbf{Water:} $>$50\% of population faces severe scarcity $\geq$1 month/year
    \item \textbf{Health:} Heat mortality \& vector-borne disease expanding
  \end{itemize}
}

% -- Source & Reference --
\posterbox[projcard, title={Source \& Reference}
]{name=source, column=3, between=row15 and row20}{
  \fontsize{30}{40}\selectfont

  \colorbox{primary!15}{\parbox{0.94\linewidth}{%
    \vspace{6pt}%
    {\fontsize{28}{36}\selectfont
    \textbf{Citation:} IPCC, 2023. \textit{AR6 Synthesis Report: Climate Change 2023.} Intergovernmental Panel on Climate Change.}\vspace{6pt}%
  }}

  \vspace{10pt}
  {\fontsize{28}{36}\selectfont
  \textbf{Data sources:}
  \begin{itemize}[itemsep=6pt, label={\color{primary}$\bullet$}]
    \item Working Group I: Physical Science Basis
    \item Working Group II: Impacts, Adaptation
    \item Working Group III: Mitigation
    \item Special Reports: 1.5\,\textdegree C, Ocean \& Cryosphere, Land
  \end{itemize}
  }

  \vspace{8pt}
  \centering
  {\fontsize{30}{38}\selectfont\color{primary}\textbf{ipcc.ch/assessment-report/ar6}}
}


\end{tcbposter}
\end{document}

